'use strict'

const fs = require('node:fs')
const path = require('node:path')

// Keep the standalone SDK independent of engine runtime packages while using
// the exact same public contract. This generated facade contains types only.
const source = path.resolve(__dirname, '../../../internals/schema/api/js/moderation.ts')
const target = path.resolve(__dirname, '../src/server/modules/moderation.ts')
const contract = fs.readFileSync(source, 'utf8')
const expectedImport = "import type { GamePlayer } from './api'"
if (!contract.includes(expectedImport)) throw new Error('Moderation contract import changed; update the SDK type adapter')
const generated = '// Generated by scripts/sync-moderation-types.js. Edit internals/schema/api/js/moderation.ts instead.\n' +
  contract.replace(expectedImport, "import type { GamePlayer } from './player'")
if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== generated) fs.writeFileSync(target, generated)
const errorSource = path.resolve(__dirname, '../../../internals/schema/api/js/error.ts')
const movementSource = path.resolve(__dirname, '../../../internals/schema/api/js/anticheat.ts')
const movementTarget = path.resolve(__dirname, '../src/server/modules/anticheat.ts')
const movementContract = '// Generated by scripts/sync-moderation-types.js. Edit internals/schema/api/js/anticheat.ts instead.\n' +
  fs.readFileSync(movementSource, 'utf8').replace("import type { GamePlayer, GameEntity, GameEventChannel } from './api';",
    "import type { GamePlayer } from './player';\nimport type { GameEntity } from './entity';\nimport type { GameEventChannel } from './events';")
if (!fs.existsSync(movementTarget) || fs.readFileSync(movementTarget, 'utf8') !== movementContract) fs.writeFileSync(movementTarget, movementContract)
const errorTarget = path.resolve(__dirname, '../src/server/modules/error.ts')
const errorContract = '// Generated by scripts/sync-moderation-types.js. Edit internals/schema/api/js/error.ts instead.\n' + fs.readFileSync(errorSource, 'utf8')
if (!fs.existsSync(errorTarget) || fs.readFileSync(errorTarget, 'utf8') !== errorContract) fs.writeFileSync(errorTarget, errorContract)
